// HYPOTHETICAL DOCUMENTATION EXCERPT (for illustration):
// Base URL: https://api.weatherexample.com/v1
// Authentication: API key as a query parameter: ?apikey=YOUR_KEY
// Endpoints:
//   GET /v1/current?city={city}&apikey={key}
//   GET /v1/forecast?city={city}&days={n}&apikey={key}
// Response shape: { "success": true, "result": { ... } } on success,
//   { "success": false, "message": "..." } on failure
// Rate limit: 60 requests per minute per API key

// APPLYING THE CHECKLIST:
// 1. Base URL/versioning: https://api.weatherexample.com/v1 - versioned,
//    so future v2 changes shouldn't break code written against v1.
// 2. Auth scheme: API key via QUERY PARAMETER, not a header - genuinely
//    different from Module 9's Bearer-header convention, so code must
//    append ?apikey=... to every request rather than setting a header.
// 3. Resource structure: 'current' and 'forecast' are the exposed
//    resources, both nested under a city query parameter rather than
//    a URL path segment like Module 7's /resource/:id pattern.
// 4. Response shape: uses 'result' instead of Module 7's own 'data'
//    convention, and 'message' instead of 'error' - similar SHAPE,
//    different specific field names - must read the actual docs
//    rather than assuming Module 7's exact field names apply universally.
// 5. Rate limits: 60/minute - relevant for lesson 3's error handling,
//    since exceeding this will produce some kind of rate-limit error
//    response that must be handled distinctly from other failures.

async function getCurrentWeather(city: string, apiKey: string) {
  const response = await fetch(
    `https://api.weatherexample.com/v1/current?city=${encodeURIComponent(city)}&apikey=${apiKey}`
  );
  const data = await response.json();
  if (!data.success) throw new Error(data.message);
  return data.result;
}

