//    explicit version segment shown.
// 2. Auth scheme: Bearer token in Authorization header - matches
//    Module 9's familiar convention directly.
// 3. Resource structure: 'books', accessed via a path parameter (:isbn),
//    matching Module 7's resource-based URL convention.
// 4. Response shape: uses 'ok' (not 'success'), 'book' (not 'data'),
//    and 'reason' (not 'error') - similar shape, different field names.
// 5. Rate limits: 100/hour - worth tracking if making many requests.

async function getBookByIsbn(isbn: string, token: string) {
  const response = await fetch(
    `https://api.bookstoreexample.com/api/books/${encodeURIComponent(isbn)}`,
    { headers: { Authorization: `Bearer ${token}` } }
  );
  const data = await response.json();
  if (!data.ok) throw new Error(data.reason);
  return data.book;
}

