import axios from 'axios';

const api = axios.create({ baseURL: '/api' });

let authToken: string | null = null;

export function setAuthToken(token: string | null) {
  authToken = token;
}

// Request interceptor - replaces Module 10 lesson 2's manual
// 'attach Authorization header if present' logic inside request()
api.interceptors.request.use((config) => {
  if (authToken) {
    config.headers.Authorization = `Bearer ${authToken}`;
  }
  return config;
});

// Response interceptor - replaces Module 10 lesson 2's manual
// 401-detection logic inside request()
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      authToken = null;
      return Promise.reject(new Error('Session expired - please log in again'));
    }
    const message = error.response?.data?.error || 'Request failed';
    return Promise.reject(new Error(message));
  }
);

export default api;

// Usage in a component - dramatically shorter than Module 10's version,
// since auth headers and 401 handling now happen automatically
async function loadTasks() {
  const response = await api.get('/tasks');
  return response.data.data; // .data is Axios's parsed body;
                               // the inner .data is this API's own
                               // envelope field, per lesson 1's
                               // 'read the actual response shape' lesson
}

