async function fetchWithLayeredErrorHandling(url: string, options?: RequestInit) {
  let response: Response;

  try {
    response = await fetch(url, options);
  } catch (networkError) {
    // CATEGORY 1: Network failure - the request never reached a server
    throw new Error('Network error - please check your connection');
  }

  if (!response.ok) {
    // CATEGORY 2: HTTP error - a server responded, but with a failure status
    if (response.status === 401) throw new Error('Authentication required');
    if (response.status === 404) throw new Error('Resource not found');
    if (response.status >= 500) throw new Error('Server error - please try again later');
    throw new Error(`Request failed with status ${response.status}`);
  }

  const data = await response.json();

  if (!data.success) {
    // CATEGORY 3: Application-level error - HTTP succeeded, but the
    // actual business operation reported failure in its own response body
    throw new Error(data.error || 'Operation failed');
  }

  return data.data;
}

