async function fetchWithRetry(
  url: string,
  options?: RequestInit,
  maxRetries: number = 3
): Promise<any> {
  let lastError: Error;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url, options);

      if (response.ok) {
        return response.json();
      }

      // Only 5xx server errors are treated as potentially transient
      // and worth retrying - 4xx client errors are NOT retried, since
      // retrying an invalid request identically will fail identically
      if (response.status < 500) {
        throw new Error(`Request failed with status ${response.status}`);
      }

      lastError = new Error(`Server error: ${response.status}`);
    } catch (err) {
      // Network failures (caught here, since fetch itself threw) ARE
      // retried, per this lesson's category-1 reasoning
      lastError = err instanceof Error ? err : new Error('Network error');
    }

    if (attempt < maxRetries) {
      const delayMs = 2 ** attempt * 1000; // exponential backoff:
                                              // 1s, 2s, 4s, ...
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }

  throw lastError!;
}

