  // TODO: implement layered error handling distinguishing:
  // - network failures (fetch itself throws) - retry with backoff
  // - HTTP errors: 4xx - throw immediately, no retry; 5xx - retry with backoff
  // - application-level errors (data.success === false) - throw immediately,
  //   no retry, using the specific data.error message
}

codingChallenge.solutionExample:
async function fetchData(url: string, maxRetries: number = 3): Promise<any> {
  let lastError: Error;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(url);

      if (!response.ok) {
        if (response.status < 500) {
          throw new Error(`Request failed with status ${response.status}`);
        }
        lastError = new Error(`Server error: ${response.status}`);
        if (attempt < maxRetries) {
          await new Promise((r) => setTimeout(r, 2 ** attempt * 1000));
          continue;
        }
        throw lastError;
      }

      const data = await response.json();
      if (!data.success) {
        throw new Error(data.error || 'Operation failed');
      }

      return data.data;
    } catch (err) {
      if (err instanceof Error && err.message.startsWith('Request failed with status')) {
        throw err; // 4xx - no retry
      }
      if (err instanceof Error && (err.message === 'Operation failed' || (err as any).isAppError)) {
        throw err; // application-level - no retry
      }
      // Treat as network failure - retry with backoff
      lastError = err instanceof Error ? err : new Error('Network error');
      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, 2 ** attempt * 1000));
        continue;
      }
      throw lastError;
    }
  }
}

