interface GraphQLResponse<T> {
  data?: T;
  errors?: { message: string }[];
}

async function graphqlRequest<T>(query: string, variables?: Record<string, unknown>): Promise<T> {
  const response = await fetch('/graphql', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables })
  });

  // NOTE: response.ok would almost always be true here, even for a
  // failed GraphQL operation - checking it alone is NOT sufficient

  const result: GraphQLResponse<T> = await response.json();

  if (result.errors && result.errors.length > 0) {
    throw new Error(result.errors[0].message);
  }

  if (!result.data) {
    throw new Error('No data returned');
  }

  return result.data;
}

// Usage, with variables instead of manually interpolating values into
// the query string directly (avoiding the exact injection-style risk
// Module 7's parameterized-query lesson warned about for SQL)
interface UserResult { user: { name: string; email: string } }

const data = await graphqlRequest<UserResult>(
  `query GetUser($id: ID!) { user(id: $id) { name email } }`,
  { id: '42' }
);
console.log(data.user.name);

