Client-side, using the browser's built-in WebSocket API:

const socket = new WebSocket('wss://example.com/chat'); // wss:// is
  // WebSocket's encrypted equivalent of https://, exactly parallel
  // to Module 1's http/https distinction

socket.addEventListener('open', () => {
  console.log('Connected');
  socket.send(JSON.stringify({ type: 'join', room: 'general' }));
});

socket.addEventListener('message', (event) => {
  const data = JSON.parse(event.data);
  console.log('Received:', data); // arrives WHENEVER the server
                                     // sends it, with no request
                                     // having been made for it
});

socket.addEventListener('close', () => {
  console.log('Connection closed');
});

Server-side (conceptually, using a typical Node.js WebSocket library):

wss.on('connection', (socket) => {
  socket.on('message', (rawMessage) => {
    const data = JSON.parse(rawMessage);
    // broadcast to all OTHER connected clients in the same room
    broadcastToRoom(data.room, data);
  });
});

