import { useState, useEffect, useRef } from 'react';

interface ChatMessage {
  id: number;
  text: string;
  sender: string;
}

function ChatRoom({ room }: { room: string }) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [connected, setConnected] = useState(false);
  const socketRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const socket = new WebSocket('wss://example.com/chat');
    socketRef.current = socket;

    socket.addEventListener('open', () => {
      setConnected(true);
      socket.send(JSON.stringify({ type: 'join', room }));
    });

    socket.addEventListener('message', (event) => {
      const message: ChatMessage = JSON.parse(event.data);
      setMessages((prev) => [...prev, message]); // append, exactly
        // Module 4's immutable-array-update discipline, still applies
    });

    socket.addEventListener('close', () => setConnected(false));

    return () => socket.close(); // CRITICAL cleanup - directly
      // extending Module 6's useEffect cleanup pattern; without this,
      // navigating away would leave the connection open indefinitely
  }, [room]);

  function sendMessage(text: string) {
    socketRef.current?.send(JSON.stringify({ type: 'message', room, text }));
  }

  return (
    <div>
      <p>{connected ? 'Connected' : 'Connecting...'}</p>
      <ul>{messages.map((m) => <li key={m.id}>{m.sender}: {m.text}</li>)}</ul>
    </div>
  );
}

